def check_digest(actual: str, expected: str, what: str) -> None:
    algo, _, hexpart = expected.partition(":")
    if algo != "sha256" or len(hexpart) != 64:
        raise DigestMismatch(f"{what}: unsupported or malformed digest {expected!r}")
