def blob(self, digest: str, dest_dir: str) -> str:
    path = os.path.join(dest_dir, digest.split(":", 1)[1])
    if not os.path.exists(path):
        tmp = path + ".part"
        self.get(f"{self.base}/blobs/{digest}", save_to=tmp)
        os.replace(tmp, path)
    return path

def _verify_blob(path: str, expected: str, what: str, gunzip: bool = False) -> None:
    try:
        image.check_digest(image.sha256_file(path, gunzip=gunzip), expected, what)
    except image.DigestMismatch:
        os.unlink(path)            # never keep (and later reuse) a blob that failed its check
        raise

# real, minibox/image.py
def clean_member_path(name: str) -> str:
    p = name.replace("\\", "/")
    while p.startswith("./"):
        p = p[2:]
    p = p.lstrip("/")
    parts = [x for x in p.split("/") if x not in ("", ".")]
    if any(x == ".." for x in parts):
        raise UnsafePath(f"tar member escapes the rootfs: {name!r}")
    return "/".join(parts)

# real, minibox/mounts.py overlay_options
def overlay_options(o: OverlayDirs) -> str:
    for p in (o.lower, o.upper, o.work):
        # ',' separates options and ':' separates lower layers; overlayfs has escaping rules for
        # them, but refusing such paths is simpler and safer than getting the escaping wrong.
        if "," in p or ":" in p:
            raise ValueError(f"overlay path may not contain ',' or ':': {p!r}")
    return f"lowerdir={o.lower},upperdir={o.upper},workdir={o.work}"

